import random
random.seed(42)

def has_short_cycle(adj, n, max_len=5):
    # BFS from each vertex to detect cycles of length <= max_len
    for s in range(n):
        # BFS
        dist = {s: 0}
        parent = {s: -1}
        from collections import deque
        q = deque([s])
        while q:
            u = q.popleft()
            if dist[u] > max_len // 2 + 1:
                continue
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u]+1
                    parent[v] = u
                    q.append(v)
                else:
                    if parent[u] != v:
                        # cycle length = dist[u] + dist[v] + 1
                        cl = dist[u] + dist[v] + 1
                        if cl <= max_len:
                            return True
    return False

def try_build(n=21, seed=0):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    edges = []
    # randomly try adding edges
    candidates = [(i,j) for i in range(n) for j in range(i+1,n)]
    random.shuffle(candidates)
    for (u,v) in candidates:
        if len(adj[u]) >= 5 or len(adj[v]) >= 5:
            continue
        # check if adding creates cycle of length < 6
        # BFS from u to v with max depth 4
        from collections import deque
        dist = {u: 0}
        q = deque([u])
        found = False
        while q:
            x = q.popleft()
            if dist[x] >= 4:
                continue
            for y in adj[x]:
                if y not in dist:
                    dist[y] = dist[x]+1
                    q.append(y)
        if v in dist and dist[v] <= 4:
            continue
        adj[u].add(v)
        adj[v].add(u)
        edges.append((u,v))
    # check min degree
    degs = [len(adj[i]) for i in range(n)]
    return adj, edges, degs

for seed in range(200):
    adj, edges, degs = try_build(21, seed)
    if min(degs) >= 3 and max(degs) <= 5:
        print("seed", seed, "degs", degs)
        print("edges", edges)
        # verify girth
        print("has short cycle:", has_short_cycle(adj, 21, 5))
